 * Calculation of total time spent on activities
 * 
 * @param {Object} activities - Object containing the activities and their durations in hours
 * 
 * @return {Number} total - total hours spent on all activities
 */
function calculateTotalTime(activities) {
    // Declare the total time as a variable to track the total hours
    let total = 0;

    // Loop through all activities in the object
    for (let activity in activities) {
        // Add the duration of the current activity to the total
        total += activities[activity];
    }

    // Return the total hours spent on all activities
    return total;
}

